package retention

import (
	"fmt"
)

// validateBatchInputs 校验一批销毁/核对请求共有的输入：
// 申请编号、处理日期、非空且去空白后无重复的档案名单。
// 返回去首尾空白后的申请编号、按提交顺序规范化的名单及名单集合。
// 任一输入无效即返回错误，调用方不得据此产生部分结果。
func validateBatchInputs(applicationID string, processedOn Date, rawIDs []string) (string, []string, map[string]struct{}, error) {
	appID, err := requireText(applicationID, "申请编号")
	if err != nil {
		return "", nil, nil, err
	}
	if err := requireDate(processedOn, "处理日期"); err != nil {
		return "", nil, nil, err
	}
	if len(rawIDs) == 0 {
		return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单为空: %w",
			appID, ErrEmptyDestructionList)
	}

	// 规范化名单并检查名单内重复（输入校验先于任何业务判断）。
	// 同一编号仅因首尾空白不同也视为重复。
	ids := make([]string, 0, len(rawIDs))
	for _, raw := range rawIDs {
		id, err := requireText(raw, "档案编号")
		if err != nil {
			return "", nil, nil, err
		}
		ids = append(ids, id)
	}
	seen := make(map[string]struct{}, len(ids))
	for _, id := range ids {
		if _, dup := seen[id]; dup {
			return "", nil, nil, fmt.Errorf("retention: 申请 %s 的销毁名单中档案 %s 重复: %w",
				appID, id, ErrDuplicateSelection)
		}
		seen[id] = struct{}{}
	}
	return appID, ids, seen, nil
}

// evaluateArchive 按当前保存状态核对一份档案在给定处理日期下的全部销毁阻碍，
// 是只读核对（Check）与正式销毁（Destroy）共用的同一份业务规则：
// 到期以当前生效的保管截止日（含修订后的日期）为准，处理日期不早于截止日即到期；
// 任一未解除冻结都是阻碍，已解除记录只保留在历史中。
//
// 阻碍按固定顺序列出：不存在、已销毁、未到期，然后是每条未解除冻结各一条
// （沿用冻结登记顺序）。已销毁的档案只带已销毁阻碍，并附所属清册的申请编号
// 和处理日期；不存在的编号只带不存在阻碍。返回结果同时携带登记内容，
// 供核对报告展示，也供正式销毁在失败时定位档案。
func evaluateArchive(data *storeData, id string, processedOn Date) ArchiveCheckResult {
	r := ArchiveCheckResult{ID: id, Obstructions: []CheckObstruction{}}
	ar, ok := data.Archives[id]
	if !ok {
		r.Obstructions = append(r.Obstructions, CheckObstruction{Kind: ObstructionMissing})
		return r
	}
	r.Exists = true
	r.Category = ar.Category
	r.Start = ar.Start
	r.End = ar.End
	r.Destroyed = ar.Destroyed

	if ar.Destroyed {
		// 已销毁档案给出所属清册的申请编号和处理日期。
		obs := CheckObstruction{Kind: ObstructionDestroyed}
		if rec, ok := data.Manifests[ar.ManifestID]; ok {
			obs.ManifestApplicationID = rec.ApplicationID
			// 通过校验的已关闭清册必然带有有效处理日期。
			if rec.ProcessedOn != nil {
				obs.ProcessedOn = *rec.ProcessedOn
			}
		} else {
			obs.ManifestApplicationID = ar.ManifestID
		}
		r.Obstructions = append(r.Obstructions, obs)
		return r
	}

	// 未到期与未解除冻结可能同时成立，两类问题都要列出。
	if processedOn.Before(ar.End) {
		r.Obstructions = append(r.Obstructions, CheckObstruction{Kind: ObstructionNotExpired})
	}
	// 每条未解除冻结各成一条阻碍，顺序沿用冻结历史（登记顺序）。
	for _, f := range ar.Freezes {
		if f.Released {
			continue
		}
		info := ActiveFreezeInfo{
			FreezeID: f.ID,
			Reason:   f.Reason,
		}
		// 通过校验的冻结必然带有有效冻结日期；防御性保留零值兜底。
		if f.FrozenOn != nil {
			info.FrozenOn = *f.FrozenOn
		}
		r.Obstructions = append(r.Obstructions, CheckObstruction{
			Kind:   ObstructionActiveFreeze,
			Freeze: info,
		})
	}
	return r
}

// firstObstructionError 把共用核对结果中的第一条阻碍转换为正式销毁的失败错误。
// 阻碍顺序固定（不存在、已销毁、未到期、未解除冻结），因此同一档案同时存在
// 多个问题时，错误类别与定位信息与既有判断先后一致。
func firstObstructionError(r ArchiveCheckResult, processedOn Date) error {
	switch obs := r.Obstructions[0]; obs.Kind {
	case ObstructionMissing:
		return fmt.Errorf("retention: 档案 %s 不存在: %w", r.ID, ErrNotFound)
	case ObstructionDestroyed:
		return fmt.Errorf("retention: 档案 %s 已在清册 %s 中，不能再次销毁: %w",
			r.ID, obs.ManifestApplicationID, ErrArchiveAlreadyOnManifest)
	case ObstructionNotExpired:
		return fmt.Errorf("retention: 档案 %s 尚未到期（截止日 %s，处理日期 %s）: %w",
			r.ID, r.End, processedOn, ErrNotExpired)
	case ObstructionActiveFreeze:
		return fmt.Errorf("retention: 档案 %s 有未解除的冻结 %s: %w",
			r.ID, obs.Freeze.FreezeID, ErrActiveFreeze)
	}
	return nil
}

// Check 在正式办理销毁前做一次只读核对。
//
// 调用者提交申请编号、处理日期和档案编号名单，得到整批申请能否办理的报告，
// 一次看清所有阻碍。核对不销毁档案、不生成或改写清册，也不占用申请编号；
// 核对后（无论报告结论如何，甚至读取本地记录失败）仍可沿用同一编号继续
// 核对或正式提交。
//
// 报告区分四种结论：
//   - CheckReady 可以办理：申请编号尚未成功使用，名单中每份档案均无阻碍；
//   - CheckBlocked 存在阻碍：申请编号尚未成功使用，至少一份档案存在阻碍，
//     Results 按提交顺序列出每份档案的核对结果和全部适用阻碍；
//   - CheckReplayable 可以取回原清册：申请编号已成功使用，且日期与档案集合
//     （顺序无关）与原申请相同，Manifest 返回原清册，不因档案已销毁而判受阻；
//   - CheckConflict 申请编号冲突：沿用该编号但改变了日期或集合，Manifest 附原清册。
//
// 申请编号已被本保管库内任意一条成功的期限修订占用时（与本次选中的档案无关，
// 该档案后来再次修订或已销毁都不释放编号），整次核对明确失败，返回
// ErrRevisionConflict，报告为空——不列出逐份档案结果，也不附清册。
// 只有成功修订才占用编号；失败过的修订提交不影响核对。
//
// 到期与冻结判断与 Destroy 共用同一份实现（evaluateArchive）：处理日期达到
// 截止日当天即到期，任一未解除冻结都会阻止销毁，已解除记录不作为阻碍。
//
// 申请编号或任一档案编号为空白、日期缺失或不是真实的 YYYY-MM-DD、
// 名单为空或含重复编号时，整次核对明确失败，不返回部分报告；
// 读取本地记录失败同样明确失败，绝不会用旧报告充当本次结果。
//
// 报告中的档案结果与清册来自同一次已保存状态读取；报告只说明核对当时的
// 情况，之后状态若变化，正式提交仍按最新状态判断。返回值是复制生成的
// 只读视图，调用者修改报告或其中清册不影响已保存的历史。
func (s *Store) Check(req CheckRequest) (CheckReport, error) {
	appID, ids, seen, err := validateBatchInputs(req.ApplicationID, req.ProcessedOn, req.ArchiveIDs)
	if err != nil {
		return CheckReport{}, err
	}

	var report CheckReport
	err = s.view(func(data *storeData) error {
		report = CheckReport{
			ApplicationID: appID,
			ProcessedOn:   req.ProcessedOn,
			Results:       make([]ArchiveCheckResult, 0, len(ids)),
		}

		// 申请编号已成功使用：只判断能否取回原清册或编号冲突，两者都附原清册。
		// 原清册取自当前这一次状态读取，与下面逐份核对看到的记录同源。
		if existing, ok := data.Manifests[appID]; ok {
			m := manifestFromRecord(existing)
			report.Manifest = &m
			if sameApplication(existing, req.ProcessedOn, seen) {
				report.Status = CheckReplayable
			} else {
				report.Status = CheckConflict
			}
			return nil
		}

		// 申请编号已被任意一条成功的期限修订占用：整次核对失败，报告为空。
		// 编号占用属于整个保管库，与本次选中的档案无关；失败过的修订不占用编号。
		if _, rec := findRevision(data, appID); rec != nil {
			return fmt.Errorf("retention: 申请编号 %s 已用于期限修订: %w",
				appID, ErrRevisionConflict)
		}

		// 申请编号尚未成功使用：按提交顺序逐份核对，每份列出全部适用阻碍。
		// 核对规则与正式销毁共用 evaluateArchive，两处结论必然一致。
		anyBlocked := false
		for _, id := range ids {
			r := evaluateArchive(data, id, req.ProcessedOn)
			if len(r.Obstructions) > 0 {
				anyBlocked = true
			}
			report.Results = append(report.Results, r)
		}

		if anyBlocked {
			report.Status = CheckBlocked
		} else {
			report.Status = CheckReady
		}
		return nil
	})
	if err != nil {
		return CheckReport{}, err
	}
	return report, nil
}

package retention

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// 以下类型是对外的只读视图，由查询方法复制内部状态生成，
// 调用方修改它们不会影响保管库中保存的记录。

// FreezeRecord 描述一条冻结及其解除信息。
// 未解除时 Released 为 false，ReleasedOn 为零值，ReleaseReason 为空。
type FreezeRecord struct {
	ID            string
	Reason        string
	FrozenOn      Date
	Released      bool
	ReleaseReason string
	ReleasedOn    Date
}

// ManifestEntry 是清册关闭瞬间档案登记内容的快照。
type ManifestEntry struct {
	ID       string
	Category string
	Start    Date
	End      Date
}

// Manifest 是一份已经关闭、内容不可更改的销毁清册。
type Manifest struct {
	ApplicationID string
	ProcessedOn   Date
	Entries       []ManifestEntry
}

// RevisionRecord 是一条已成功办理的保管截止日修订记录。
//
// OldEnd 是修订前生效的截止日，NewEnd 是修订后生效的截止日；
// RevisedOn 仅用于记录办理日期，提交成功即采用新期限。
type RevisionRecord struct {
	RevisionID string
	ArchiveID  string
	OldEnd     Date
	NewEnd     Date
	RevisedOn  Date
	Reason     string
}

// ArchiveHistory 是按档案编号核对时看到的完整历史。
type ArchiveHistory struct {
	ID       string
	Category string
	Start    Date
	// InitialEnd 是最初登记时的保管截止日，不随修订改变。
	InitialEnd Date
	// RetentionEnd 是当前生效的保管截止日，等于最后一次成功修订的新截止日；
	// 从未修订过时与 InitialEnd 相同。
	RetentionEnd          Date
	Destroyed             bool
	ManifestApplicationID string
	// Revisions 包含全部截止日修订记录，按成功办理顺序排列。
	Revisions []RevisionRecord
	// Freezes 包含全部冻结及解除历史，按登记顺序排列。
	Freezes []FreezeRecord
	// ActiveFreezes 仅包含尚未解除的冻结。
	ActiveFreezes []FreezeRecord
	// Manifest 是该档案销毁时生成的已关闭清册；未销毁时为 nil。
	Manifest *Manifest
}

// CheckStatus 是整批销毁前核对报告的总体结论。
type CheckStatus string

const (
	// CheckReady 表示申请编号尚未成功使用，且名单中每份档案都没有阻碍，可以办理销毁。
	CheckReady CheckStatus = "可以办理"
	// CheckBlocked 表示申请编号尚未成功使用，但名单中至少一份档案存在阻碍。
	CheckBlocked CheckStatus = "存在阻碍"
	// CheckReplayable 表示申请编号已成功使用，本次日期与档案集合与原申请相同，可以取回原清册。
	CheckReplayable CheckStatus = "可以取回原清册"
	// CheckConflict 表示申请编号已成功使用，但本次日期或档案集合与原申请不一致。
	CheckConflict CheckStatus = "申请编号冲突"
)

// ObstructionKind 标识一份档案不能办理销毁的具体原因类别，调用者可逐一识别。
type ObstructionKind string

const (
	// ObstructionMissing 表示该编号在保管库中不存在。
	ObstructionMissing ObstructionKind = "不存在"
	// ObstructionDestroyed 表示该档案已经销毁，并附所属清册信息。
	ObstructionDestroyed ObstructionKind = "已销毁"
	// ObstructionNotExpired 表示按处理日期档案尚未到保管截止日（截止日当天才到期）。
	ObstructionNotExpired ObstructionKind = "未到期"
	// ObstructionActiveFreeze 表示档案仍有一条未解除的冻结；每份未解除冻结对应一条阻碍。
	ObstructionActiveFreeze ObstructionKind = "仍有未解除冻结"
)

// ActiveFreezeInfo 是核对时看到的一条未解除冻结，字段取自冻结历史登记顺序。
type ActiveFreezeInfo struct {
	FreezeID string
	Reason   string
	FrozenOn Date
}

// CheckObstruction 描述一份档案的一条适用阻碍。
//
// 一份未到期且有多条未解除冻结的档案会同时列出未到期阻碍和
// 每条冻结各一条阻碍；冻结阻碍按冻结历史登记顺序排列。
// 仅 ObstructionDestroyed 时 ManifestApplicationID 与 ProcessedOn 有意义，
// 给出所属清册的申请编号和处理日期。
type CheckObstruction struct {
	Kind                  ObstructionKind
	Freeze                ActiveFreezeInfo
	ManifestApplicationID string
	ProcessedOn           Date
}

// ArchiveCheckResult 是名单中一份档案的核对结果，按调用者提交顺序出现。
//
// 已登记档案无论能否办理都带类别、起算日、截止日和销毁状态；
// 编号不存在时 Exists 为 false，登记字段为零值，且只带一条 ObstructionMissing 阻碍，
// 不影响名单中其他档案继续核对。
type ArchiveCheckResult struct {
	ID        string
	Exists    bool
	Category  string
	Start     Date
	End       Date
	Destroyed bool
	// Obstructions 列出全部适用阻碍；为空表示该档案按当前状态可以销毁。
	Obstructions []CheckObstruction
}

// CheckReport 是一次只做核对的完整结果。
//
// 报告中的档案结果与清册全部来自同一次已保存状态读取，不会混入其他程序
// 办理前后的不同结果。报告及其中清册均为复制生成的只读视图，调用者修改
// 不影响保管库中保存的历史。报告只说明核对当时的情况，不预占状态：
// 之后新增冻结或其他程序先完成销毁，正式提交仍按最新状态判断。
type CheckReport struct {
	ApplicationID string
	ProcessedOn   Date
	Status        CheckStatus
	// Results 按提交顺序列出每份档案的核对结果（申请编号未成功使用时）。
	Results []ArchiveCheckResult
	// Manifest 仅在状态为可以取回原清册或申请编号冲突时附带原清册，其余情况为 nil。
	Manifest *Manifest
}

// 以下类型是持久化到磁盘的数据结构，仅在包内使用。

type archiveRecord struct {
	ID         string            `json:"id"`
	Category   string            `json:"category"`
	Start      Date              `json:"start"`
	End        Date              `json:"end"`
	InitialEnd Date              `json:"initial_end,omitempty"`
	Destroyed  bool              `json:"destroyed"`
	ManifestID string            `json:"manifest_id,omitempty"`
	Freezes    []*freezeRecord   `json:"freezes"`
	Revisions  []*revisionRecord `json:"revisions,omitempty"`
}

// UnmarshalJSON 逐字段解码一份档案的登记记录，守住“同一份档案的保存内容中
// 冻结列表 freezes 与修订列表 revisions 各自最多只能出现一次”的要求。
//
// 直接把登记记录解码进结构体时，encoding/json 对同名字段只保留最后一个值：
// 同一份档案的保存内容中若写了两次 freezes，先保存的冻结历史会被后一次静默
// 替换（例如先保存包含未解除诉讼冻结的 freezes，后面又保存一个空的 freezes，
// 读取后历史里原冻结消失，到期后的销毁前核对可能误报可以办理）；写了两次
// revisions 时，先保存的修订历史同样会被后一次静默替换（例如第一处保存着
// 先延长后缩短回最初期限的两条修订、第二处是空列表，读取后当前截止日仍与
// 最初期限一致、保管库仍能打开，但两次修订消失，已占用的修订编号也可能被
// 重新用于新业务）。这样的记录不能被当成没有冻结或没有修订的正常档案使用。
//
// 因此这里逐个读取登记记录的字段名：字段名按 JSON 字符串解码后的实际文本
// 识别——直接写出的 "freezes"/"revisions" 与通过 Unicode 转义写出、解码后
// 相同的写法是同一个字段；现有能识别为对应列表的大小写写法（如 "Freezes"/
// "Revisions"，沿用 encoding/json 的大小写不敏感匹配）单独出现时继续可读，
// 与标准写法混用重复保存同样算重复。同一列表第二次出现时立即返回对应的
// 重复字段错误（errDuplicateFreezesField / errDuplicateRevisionsField）：
// 两处列表内容是否完全一致、是否分别保存不同记录、其中一处是否为空列表或
// null，都不影响拒绝——绝不合并两处列表、不挑选其中一份，拒绝结果与两处的
// 保存顺序无关。
//
// 检查只针对这份档案自己的保存内容：不同档案各自的冻结列表、修订列表互不
// 影响，冻结与修订记录内部的同名字段（id、原因、日期）也不是列表字段，不会
// 被误判；其余字段保持既有读取行为（同名字段沿用 encoding/json 的后者覆盖
// 前者，未知字段跳过）。
func (r *archiveRecord) UnmarshalJSON(raw []byte) error {
	// 记录保存为 null 时保持零值（与 encoding/json 对 null 的既有行为一致），
	// 缺少有效 id 等问题由 load 的语义校验按损坏报告。
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return nil
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	startTok, err := dec.Token()
	if err != nil {
		return err
	}
	if delim, ok := startTok.(json.Delim); !ok || delim != '{' {
		return fmt.Errorf("retention: 档案登记记录不是 JSON 对象")
	}
	freezesSeen := false
	revisionsSeen := false
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := keyTok.(string)
		if !ok {
			return fmt.Errorf("retention: 档案登记记录的字段名不是 JSON 字符串")
		}
		switch {
		case strings.EqualFold(key, "freezes"):
			// 重复检查必须先于解码：即使第二处为空列表或 null，也不能让它
			// 把先保存的冻结历史整批替换后继续使用。
			if freezesSeen {
				return errDuplicateFreezesField
			}
			freezesSeen = true
			if err := dec.Decode(&r.Freezes); err != nil {
				return err
			}
		case strings.EqualFold(key, "id"):
			if err := dec.Decode(&r.ID); err != nil {
				return err
			}
		case strings.EqualFold(key, "category"):
			if err := dec.Decode(&r.Category); err != nil {
				return err
			}
		case strings.EqualFold(key, "start"):
			if err := dec.Decode(&r.Start); err != nil {
				return err
			}
		case strings.EqualFold(key, "end"):
			if err := dec.Decode(&r.End); err != nil {
				return err
			}
		case strings.EqualFold(key, "initial_end"):
			if err := dec.Decode(&r.InitialEnd); err != nil {
				return err
			}
		case strings.EqualFold(key, "destroyed"):
			if err := dec.Decode(&r.Destroyed); err != nil {
				return err
			}
		case strings.EqualFold(key, "manifest_id"):
			if err := dec.Decode(&r.ManifestID); err != nil {
				return err
			}
		case strings.EqualFold(key, "revisions"):
			// 重复检查必须先于解码：即使第二处为空列表或 null，也不能让它
			// 把先保存的修订历史整批替换后继续使用（当前截止日仍与最初期限
			// 一致时保管库看似正常，但修订记录与已占用的修订编号已经消失）。
			if revisionsSeen {
				return errDuplicateRevisionsField
			}
			revisionsSeen = true
			if err := dec.Decode(&r.Revisions); err != nil {
				return err
			}
		default:
			// 未知字段与既有行为一致：跳过不校验。
			var skip json.RawMessage
			if err := dec.Decode(&skip); err != nil {
				return err
			}
		}
	}
	// 消费对象结束括号，确保整个值恰好是一个对象。
	if _, err := dec.Token(); err != nil {
		return err
	}
	return nil
}

// errDuplicateFreezesField 表示同一份档案的保存内容中冻结列表 freezes 出现了
// 两次或更多次。它在解码时尚不知道档案编号（编号是集合对象的键），由
// archiveMap 在解码出错的键处包装成 duplicateFreezesFieldError 并附上编号，
// 再由 load 统一包装成可由 ErrCorruptState 识别的错误。
var errDuplicateFreezesField = errors.New("retention: 冻结列表 freezes 在单份档案的保存内容中出现了多次")

// duplicateFreezesFieldError 表示档案 ID 的保存内容中冻结列表 freezes 出现了
// 两次或更多次。错误说明重复的是冻结列表本身，而不是某个冻结编号重复。
type duplicateFreezesFieldError struct {
	ID string
}

func (e *duplicateFreezesFieldError) Error() string {
	return "retention: 档案 " + e.ID + " 的保存内容中冻结列表 freezes 出现了多次"
}

// errDuplicateRevisionsField 表示同一份档案的保存内容中修订列表 revisions 出现了
// 两次或更多次。它在解码时尚不知道档案编号（编号是集合对象的键），由
// archiveMap 在解码出错的键处包装成 duplicateRevisionsFieldError 并附上编号，
// 再由 load 统一包装成可由 ErrCorruptState 识别的错误。
var errDuplicateRevisionsField = errors.New("retention: 修订列表 revisions 在单份档案的保存内容中出现了多次")

// duplicateRevisionsFieldError 表示档案 ID 的保存内容中修订列表 revisions 出现了
// 两次或更多次。错误说明重复的是修订列表本身，而不是某个修订编号重复。
type duplicateRevisionsFieldError struct {
	ID string
}

func (e *duplicateRevisionsFieldError) Error() string {
	return "retention: 档案 " + e.ID + " 的保存内容中修订列表 revisions 出现了多次"
}

// revisionRecord 是一条已保存的截止日修订；文本字段保存时均已去除首尾空白。
type revisionRecord struct {
	ID     string `json:"id"`
	OldEnd Date   `json:"old_end"`
	NewEnd Date   `json:"new_end"`
	// RevisedOn 用指针保存：修订缺少修订日期或保存为 null 时保持 nil
	// （encoding/json 对 null 指针不调用 Date.UnmarshalJSON），由 load 的
	// 语义校验按损坏报告（并能指出档案编号与修订编号），而不是落入 JSON
	// 解析错误或被零值日期顶替；一旦给出字符串，Date.UnmarshalJSON 按 JSON
	// 解码后的实际文本校验真实日期，非法文本（含不是合法日历日期的值）直接
	// 使解码失败。通过校验的修订必然带有有效修订日期。
	RevisedOn *Date  `json:"revised_on"`
	Reason    string `json:"reason"`
}

type freezeRecord struct {
	ID     string `json:"id"`
	Reason string `json:"reason"`
	// FrozenOn 用指针保存：冻结缺少冻结日期或保存为 null 时保持 nil，
	// 由 load 的语义校验按损坏报告（并能指出档案编号与冻结编号），而不是
	// 落入 JSON 解析错误或被零值日期顶替。通过校验的冻结必然带有有效冻结日期。
	FrozenOn      *Date  `json:"frozen_on"`
	Released      bool   `json:"released"`
	ReleaseReason string `json:"release_reason,omitempty"`
	// ReleasedOn 用指针保存：字段缺失或保存为 null 时保持 nil（encoding/json
	// 对 null 指针不调用 Date.UnmarshalJSON），由 load 的语义校验按损坏报告；
	// 一旦给出字符串，Date.UnmarshalJSON 按 JSON 解码后的实际文本校验真实
	// 日期，非法文本（含转义后出现加号、空白等）直接使解码失败。
	ReleasedOn *Date `json:"released_on,omitempty"`
}

// UnmarshalJSON 逐字段解码一条冻结记录，守住“同一条冻结记录的保存内容中解除
// 标记 released 最多只能出现一次”的要求。
//
// 直接把冻结记录解码进结构体时，encoding/json 对同名字段只保留最后一个值：
// 同一条冻结的保存内容中若先写了 released:false、后面又写 released:true 并
// 带上合法的解除原因和解除日期，读取会采用后一个标记——档案到期后，销毁前
// 核对可能误报可以办理，正式销毁也会忽略这条冻结。这样的记录不能被当成解除
// 状态明确的正常冻结使用。
//
// 因此这里逐个读取冻结记录的字段名：字段名按 JSON 字符串解码后的实际文本
// 识别——直接写出的 "released" 与通过 Unicode 转义写出、解码后相同的写法是
// 同一个标记；现有能识别为解除标记的大小写写法（如 "Released"，沿用
// encoding/json 的大小写不敏感匹配）单独出现时继续可读，与标准写法混用重复
// 保存同样算重复。解除标记第二次出现时立即返回 duplicateReleasedFieldError：
// 两处取值相反、完全相同，或其中一处为 null，都不影响拒绝——绝不选取其中
// 一个值继续使用，拒绝结果与两处的保存顺序无关。
//
// 检查只针对这条冻结自己的保存内容：同一档案不同冻结、不同档案各自的解除
// 标记不合在一起计数；其余字段保持既有读取行为（同名字段沿用 encoding/json
// 的后者覆盖前者，未知字段跳过）。
func (r *freezeRecord) UnmarshalJSON(raw []byte) error {
	// 记录保存为 null 时保持零值（与 encoding/json 对 null 的既有行为一致），
	// 空冻结记录由 load 的语义校验按损坏报告。
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return nil
	}
	// 冻结编号可能写在重复的解除标记之后，先单独取出用于错误信息；
	// 编号缺失、为空白等问题由 load 的语义校验按损坏报告。
	var probe struct {
		ID string `json:"id"`
	}
	_ = json.Unmarshal(raw, &probe)
	dec := json.NewDecoder(bytes.NewReader(raw))
	startTok, err := dec.Token()
	if err != nil {
		return err
	}
	if delim, ok := startTok.(json.Delim); !ok || delim != '{' {
		return fmt.Errorf("retention: 冻结记录不是 JSON 对象")
	}
	releasedSeen := false
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := keyTok.(string)
		if !ok {
			return fmt.Errorf("retention: 冻结记录的字段名不是 JSON 字符串")
		}
		switch {
		case strings.EqualFold(key, "released"):
			// 重复检查必须先于解码：即使第二处取相反的值、完全相同的值或为
			// null，也不能让后一个标记顶替先保存的解除状态后继续使用。
			if releasedSeen {
				return &duplicateReleasedFieldError{FreezeID: probe.ID}
			}
			releasedSeen = true
			if err := dec.Decode(&r.Released); err != nil {
				return err
			}
		case strings.EqualFold(key, "id"):
			if err := dec.Decode(&r.ID); err != nil {
				return err
			}
		case strings.EqualFold(key, "reason"):
			if err := dec.Decode(&r.Reason); err != nil {
				return err
			}
		case strings.EqualFold(key, "frozen_on"):
			if err := dec.Decode(&r.FrozenOn); err != nil {
				return err
			}
		case strings.EqualFold(key, "release_reason"):
			if err := dec.Decode(&r.ReleaseReason); err != nil {
				return err
			}
		case strings.EqualFold(key, "released_on"):
			if err := dec.Decode(&r.ReleasedOn); err != nil {
				return err
			}
		default:
			// 未知字段与既有行为一致：跳过不校验。
			var skip json.RawMessage
			if err := dec.Decode(&skip); err != nil {
				return err
			}
		}
	}
	// 消费对象结束括号，确保整个值恰好是一个对象。
	if _, err := dec.Token(); err != nil {
		return err
	}
	return nil
}

// duplicateReleasedFieldError 表示同一条冻结记录的保存内容中解除标记 released
// 出现了两次或更多次。错误说明重复的是解除标记 released 本身，而不是冻结编号
// 或冻结列表重复。FreezeID 在 freezeRecord 解码时填入（冻结编号可能写在重复
// 标记之后，由单独的一次预解码取出），ArchiveID 由 archiveMap 在解码出错的
// 键处补上，再由 load 统一包装成可由 ErrCorruptState 识别的错误。
type duplicateReleasedFieldError struct {
	ArchiveID string
	FreezeID  string
}

func (e *duplicateReleasedFieldError) Error() string {
	return "retention: 档案 " + e.ArchiveID + " 的冻结 " + e.FreezeID + " 的保存内容中解除标记 released 出现了多次"
}

type manifestRecord struct {
	ApplicationID string `json:"application_id"`
	// ProcessedOn 用指针保存：清册缺少处理日期或保存为 null 时保持 nil，
	// 由 load 的语义校验按损坏报告（并能指出申请编号），而不是落入 JSON 解析错误。
	// 通过校验的已关闭清册必然带有有效处理日期。
	ProcessedOn *Date           `json:"processed_on"`
	Entries     []manifestEntry `json:"entries"`
}

type manifestEntry struct {
	ID       string `json:"id"`
	Category string `json:"category"`
	Start    Date   `json:"start"`
	End      Date   `json:"end"`
}

// unmarshalKeyedRecordMap 按档案集合与清册集合共同的读取规则解码一个以编号
// 为键、逐项保存记录的 JSON 对象；两类集合共同的集合格式、编号解码与重复键
// 核对只在这里维护一份。
//
// 共同读取规则：
//   - 集合保存为 null 时按空集合处理（字段缺失时根本不会进入这里），保留既有
//     的空集合兼容行为；
//   - 值必须恰好是一个 JSON 对象，第一个 token 不是对象左括号即报错；
//   - 逐个读取对象键：键必须是 JSON 字符串，编号按 JSON 字符串解码后的实际
//     文本识别——直接写出的编号与通过 Unicode 转义写出、解码后相同的编号是
//     同一个键。检查只针对集合对象自身的键，记录内部的同名字段（如每份登记
//     的 "id"、每份清册的 "application_id" 与条目里的 "id"）不是集合键，不会
//     被当成重复编号；
//   - 逐键把对应值解码成一条记录（记录内容的结构由类型参数 T 决定），同一
//     解码后编号出现第二次时立即返回 duplicate(id)：绝不以后一份覆盖前一份，
//     两份内容是否完全相同、期限、冻结状态或处理日期有何差别都不影响拒绝；
//   - 最后消费对象结束括号，保证整个值恰好是一个对象；对象之后再拼接任何内容
//     由外层 json.Unmarshal 的“整值恰好一个 JSON 值”校验拒绝。
//
// 两类集合各自不同、不在这里合并的部分由参数传入：fieldName 与 idKind 只用于
// 错误信息，T 决定每条记录的内容结构，duplicate 按解码出的重复编号构造该集合
// 自己的重复错误（档案集合说明重复登记，清册集合说明同一申请对应多份清册），
// 再由 load 统一包装成 ErrCorruptState。recordErr 在逐键解码单条记录出错时
// 用该记录的查找编号包装错误（档案集合用它给冻结列表、修订列表重复错误附上
// 档案编号），为 nil 时记录解码错误原样返回。
func unmarshalKeyedRecordMap[T any](raw []byte, fieldName, idKind string, duplicate func(id string) error, recordErr func(id string, err error) error) (map[string]*T, error) {
	// 集合保存为 null 与字段缺失等价，按空集合处理（与既有兼容行为一致）。
	if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return map[string]*T{}, nil
	}
	// 先用只保留键文本的解码拿到稳定的键序，再逐键把原始片段解码成记录，
	// 保证同编号键出现两次时不是“后者覆盖前者”，而是明确报错。
	dec := json.NewDecoder(bytes.NewReader(raw))
	startTok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	if delim, ok := startTok.(json.Delim); !ok || delim != '{' {
		return nil, fmt.Errorf("retention: %s 字段不是 JSON 对象", fieldName)
	}

	out := map[string]*T{}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		id, ok := keyTok.(string)
		if !ok {
			return nil, fmt.Errorf("retention: %s 字段的%s不是 JSON 字符串", fieldName, idKind)
		}
		var rec T
		if err := dec.Decode(&rec); err != nil {
			if recordErr != nil {
				return nil, recordErr(id, err)
			}
			return nil, err
		}
		if _, dup := out[id]; dup {
			return nil, duplicate(id)
		}
		out[id] = &rec
	}
	// 消费对象结束括号，确保整个值恰好是一个对象。
	if _, err := dec.Token(); err != nil {
		return nil, err
	}
	return out, nil
}

// archiveMap 以档案编号为键保存登记记录，并在从 JSON 解码时守住
// “一个档案编号只能登记一次”的要求。
//
// 直接把对象解码进普通 map 时，encoding/json 对同名键只会保留最后一个
// 值：保存内容中若写了两份同编号登记，前一份会被静默覆盖（例如前一份带着
// 未解除的诉讼冻结、后一份冻结列表为空，读取后只剩后一份，销毁资格会被
// 误判）。除键不重复外，每条记录的身份还必须自洽：用于找到该记录的键与
// 记录内容里的 id 必须同为非空白文本且逐字相同。键与 id 是两处独立保存的
// 文本，普通解码不会核对它们，可能出现挂在 A-1 名下、id 却写成 A-2，或
// id 缺失、为 null、空串、只有空白的记录——按 A-1 查到的历史会标着 A-2，
// 销毁还可能把 A-2 写进清册。这层检查不在 UnmarshalJSON 中完成（解码只
// 负责拒绝重复键），而由 load 的 validateArchiveIdentity 在进入任何业务
// 操作前统一核对，命中即包装成 ErrCorruptState：绝不做去空白、大小写
// 归一化、改号或补写缺失编号。
type archiveMap map[string]*archiveRecord

// UnmarshalJSON 逐键解码档案集合，发现重复编号即报 duplicateArchiveIDError。
// 集合格式、编号按 JSON 解码实际文本识别、记录内部同名字段不算集合键等
// 共同读取规则统一由 unmarshalKeyedRecordMap 维护，这里只传入档案集合自己的
// 字段名、编号称谓与重复错误。逐键解码单份登记记录时，若记录自己的保存内容
// 中冻结列表 freezes 或修订列表 revisions 出现了两次或更多次
// （archiveRecord.UnmarshalJSON 返回 errDuplicateFreezesField /
// errDuplicateRevisionsField），或某条冻结自己的保存内容中解除标记 released
// 出现了两次或更多次（freezeRecord.UnmarshalJSON 返回
// duplicateReleasedFieldError），在这里用该记录的查找编号包装成
// duplicateFreezesFieldError / duplicateRevisionsFieldError，或为
// duplicateReleasedFieldError 补上档案编号——重复检查只针对这份档案、这条
// 冻结自己的保存内容，不同档案各自的列表、不同冻结各自的解除标记不会合在
// 一起计数。
func (m *archiveMap) UnmarshalJSON(raw []byte) error {
	out, err := unmarshalKeyedRecordMap[archiveRecord](raw, "archives", "档案编号",
		func(id string) error { return &duplicateArchiveIDError{ID: id} },
		func(id string, err error) error {
			if errors.Is(err, errDuplicateFreezesField) {
				return &duplicateFreezesFieldError{ID: id}
			}
			if errors.Is(err, errDuplicateRevisionsField) {
				return &duplicateRevisionsFieldError{ID: id}
			}
			// 单条冻结记录自己的保存内容中解除标记 released 出现了两次或更多次
			// 时，在这里用该记录的查找编号补上档案编号——重复检查只针对这条
			// 冻结自己的保存内容，不同冻结、不同档案各自的解除标记不合在一起
			// 计数。
			var dupReleased *duplicateReleasedFieldError
			if errors.As(err, &dupReleased) {
				dupReleased.ArchiveID = id
				return dupReleased
			}
			return err
		})
	if err != nil {
		return err
	}
	*m = archiveMap(out)
	return nil
}

// duplicateArchiveIDError 表示保存的档案集合中同一编号出现了多次。
// 它在包内由 load 统一包装成可由 ErrCorruptState 识别的错误。
type duplicateArchiveIDError struct {
	ID string
}

func (e *duplicateArchiveIDError) Error() string {
	return "retention: 档案编号 " + e.ID + " 在保存的档案集合中登记了多次"
}

// manifestMap 以申请编号为键保存已关闭清册，并在从 JSON 解码时守住
// “一个已成功的销毁申请编号只能对应一份已关闭清册”的要求。
//
// 直接把对象解码进普通 map 时，encoding/json 对同名键只会保留最后一个
// 值：保存内容中若写了两份同申请编号的清册，前一份会被静默覆盖。由于两份
// 清册可能各自都符合档案归属、条目快照、期限与处理日期规则，仅留下后一份
// 时保管库仍能打开，取回的清册随保存顺序改变——已成功的销毁申请只能对应
// 一份已关闭清册，这种重复保存不是正常的申请重试（幂等重放应取回唯一的原
// 清册，绝不应在保存层产生两份记录）。UnmarshalJSON 逐键解码并按解码后的
// 实际文本核对申请编号，出现重复时返回 duplicateApplicationIDError，由
// load 统一包装成 ErrCorruptState。除键不重复外，每份清册的身份还必须
// 自洽：用于找到该清册的键与清册内容里的 application_id 必须同为非空白
// 文本且逐字相同——可能出现挂在 APP-1 名下、application_id 却写成 APP-2，
// 或 application_id 缺失、为 null、空串、只有空白的记录，此时按 APP-1
// 取回的清册会标着 APP-2，重提原申请也会拿到编号不符的清册。这层检查
// 不在 UnmarshalJSON 中完成（解码只负责拒绝重复键），而由 load 的
// validateManifestIdentity 在进入任何业务操作前统一核对，命中即包装成
// ErrCorruptState：绝不做去空白、大小写归一化、用查找编号补写清册、
// 以清册内容改号或删除冲突记录。
type manifestMap map[string]*manifestRecord

// UnmarshalJSON 逐键解码清册集合，发现同一申请编号对应两份清册即报
// duplicateApplicationIDError。集合格式、编号按 JSON 解码实际文本识别、
// 记录内部同名字段不算集合键等共同读取规则统一由 unmarshalKeyedRecordMap
// 维护，这里只传入清册集合自己的字段名、编号称谓与重复错误。
func (m *manifestMap) UnmarshalJSON(raw []byte) error {
	out, err := unmarshalKeyedRecordMap[manifestRecord](raw, "manifests", "申请编号",
		func(id string) error { return &duplicateApplicationIDError{ID: id} }, nil)
	if err != nil {
		return err
	}
	*m = manifestMap(out)
	return nil
}

// duplicateApplicationIDError 表示保存的清册集合中同一申请编号对应了多份
// 清册。它在包内由 load 统一包装成可由 ErrCorruptState 识别的错误。
type duplicateApplicationIDError struct {
	ID string
}

func (e *duplicateApplicationIDError) Error() string {
	return "retention: 申请编号 " + e.ID + " 在保存的清册集合中对应了多份清册"
}

type storeData struct {
	Version   int         `json:"version"`
	Archives  archiveMap  `json:"archives"`
	Manifests manifestMap `json:"manifests"`
}

// UnmarshalJSON 逐键解码保存记录的最外层对象，守住“同一份保存记录的最外层
// 最多只能出现一次档案集合，也最多只能出现一次清册集合”的要求。
//
// 直接把最外层对象解码进结构体时，encoding/json 对同名字段只会保留最后一个
// 值：保存内容中若写了两次 archives，前一次保存的档案集合会被后一次静默替换
// （例如第一处保存着带未解除诉讼冻结的 A-1，第二处保存成没有冻结的同号档案，
// 读取后只剩后者，销毁资格会被误判为可以办理）；写了两次 manifests 时前一份
// 清册集合同样会被后一份整批替换——两份清册可能各自都符合档案归属、条目快照、
// 期限与处理日期规则（例如 APP-1 的清册收录截止日为 2025-01-10 的已销毁档案，
// 两处处理日期分别为 2025-01-10 和 2025-01-11，两个日期都满足到期规则），仅
// 留下后一份时保管库仍能打开，取回的处理日期却随保存顺序变化。已关闭清册的
// 历史不能这样被覆盖。
//
// 因此这里逐个读取最外层字段名：字段名按 JSON 字符串解码后的实际文本识别——
// 直接写出的 "archives"/"manifests" 与通过 Unicode 转义写出、解码后相同的写法
// 是同一个字段；现有能识别为对应集合的大小写写法（如 "Archives"/"Manifests"，
// 沿用 encoding/json 的大小写不敏感匹配）单独出现时继续可读，与标准写法混用
// 重复保存同样算重复。同一集合字段第二次出现时立即返回对应的重复字段错误：
// 两处集合内容是否完全一致、是否只含不同编号（清册两处分别只含不同申请）、
// 其中一处是否为空对象或 null，都不影响拒绝——绝不合并、不取最后一份，也不
// 按处理日期、收录档案或哪份保留了更多冻结挑选，拒绝结果与两处的保存顺序无关。
//
// 检查只针对最外层的集合字段：各份档案登记内容里各自出现的 id、日期、冻结等
// 同名字段是正常保存格式，多份清册内部各自带有的申请编号、处理日期和条目字段
// 也是正常保存格式，不会被误判为最外层集合重复；集合内部同一编号出现两次仍
// 分别由 archiveMap.UnmarshalJSON 与 manifestMap.UnmarshalJSON 按既有规则拒绝。
func (d *storeData) UnmarshalJSON(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	startTok, err := dec.Token()
	if err != nil {
		return err
	}
	if delim, ok := startTok.(json.Delim); !ok || delim != '{' {
		return fmt.Errorf("retention: 保存记录不是 JSON 对象")
	}
	archivesSeen := false
	manifestsSeen := false
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := keyTok.(string)
		if !ok {
			return fmt.Errorf("retention: 保存记录最外层的字段名不是 JSON 字符串")
		}
		switch {
		case strings.EqualFold(key, "archives"):
			if archivesSeen {
				return &duplicateArchivesFieldError{}
			}
			archivesSeen = true
			if err := dec.Decode(&d.Archives); err != nil {
				return err
			}
		case strings.EqualFold(key, "manifests"):
			// 重复检查必须先于解码：即使第二处为空对象或 null，也不能让它
			// 把第一处清册集合整批替换成空集合后继续使用。
			if manifestsSeen {
				return &duplicateManifestsFieldError{}
			}
			manifestsSeen = true
			if err := dec.Decode(&d.Manifests); err != nil {
				return err
			}
		case strings.EqualFold(key, "version"):
			if err := dec.Decode(&d.Version); err != nil {
				return err
			}
		default:
			// 未知字段与既有行为一致：跳过不校验。
			var skip json.RawMessage
			if err := dec.Decode(&skip); err != nil {
				return err
			}
		}
	}
	// 消费对象结束括号，确保整个值恰好是一个对象。
	if _, err := dec.Token(); err != nil {
		return err
	}
	return nil
}

// duplicateArchivesFieldError 表示保存记录的最外层出现了两次或更多次档案
// 集合 archives。它在包内由 load 统一包装成可由 ErrCorruptState 识别的错误；
// 错误说明重复的是档案集合本身，不涉及任何具体档案编号。
type duplicateArchivesFieldError struct{}

func (e *duplicateArchivesFieldError) Error() string {
	return "retention: 保存记录最外层的档案集合 archives 出现了多次"
}

// duplicateManifestsFieldError 表示保存记录的最外层出现了两次或更多次清册
// 集合 manifests。它在包内由 load 统一包装成可由 ErrCorruptState 识别的错误；
// 错误说明重复的是清册集合本身，而不是某个申请编号在集合内重复——即使两处
// 分别只含不同申请，重复的也只是集合字段。
type duplicateManifestsFieldError struct{}

func (e *duplicateManifestsFieldError) Error() string {
	return "retention: 保存记录最外层的清册集合 manifests 出现了多次"
}

func newStoreData() *storeData {
	return &storeData{
		Version:   1,
		Archives:  archiveMap{},
		Manifests: manifestMap{},
	}
}

package retention

import (
	"errors"
	"strings"
	"testing"
)

// 多条冻结同时存在问题时，调用者得到的错误说明必须遵守既有先后关系：
//
//   - 原冻结信息缺项（缺少冻结原因或冻结日期）整体优先于解除信息错误
//     （已解除却缺少解除原因、解除日期，或解除日期早于冻结日期）：即使解除
//     问题属于编号更靠前的档案，或出现在同一档案更早登记的冻结中，也必须先
//     报告按既定顺序选出的原冻结信息缺项；
//   - 同类问题出现多处时，按档案编号的文本升序、再按该档案冻结历史的登记
//     顺序选出首个问题——冻结编号大小与日期先后都不能替代登记顺序，不同档案
//     在保存内容中的排列位置也不能改变报告；
//   - 同一条冻结同时缺少原冻结原因与冻结日期时两项都说明，完整的解除信息
//     不能代替原冻结信息；同一条已解除记录同时缺少解除原因与解除日期时先
//     说明解除原因；日期倒置时同时给出解除日期与冻结日期。
//
// 本文件只补充这些错误共同出现时的回归保障，不改变任何办理规则与错误类别：
// 命中时仍是 ErrCorruptState，错误仍带档案编号、冻结编号与具体问题。

// frz 拼装一条冻结记录，body 是紧跟在 id 之后的字段片段（需自带前导逗号）。
func frz(id, body string) string {
	return `{"id":"` + id + `",` + body + `}`
}

// freezeErrorState 拼装一个只含未销毁档案、不含清册的保存记录，
// archives 按传入顺序排列，用于验证档案在保存内容中的排列位置不影响报告。
func freezeErrorState(archives ...string) string {
	return `{"version":1,"archives":{` + strings.Join(archives, ",") + `},"manifests":{}}`
}

func freezeErrorArchive(id string, freezes ...string) string {
	return `"` + id + `":{"id":"` + id +
		`","category":"合同","start":"2020-01-01","end":"2026-12-31",` +
		`"initial_end":"2026-12-31","destroyed":false,"freezes":[` +
		strings.Join(freezes, ",") + `]}`
}

// 原冻结信息缺项与解除信息错误共同出现时，必须先报告原冻结信息缺项。
func TestFreezeCorruptionOriginErrorsTakePrecedence(t *testing.T) {
	const (
		// 已解除但缺少解除原因（解除信息错误）。
		releasedMissingReason = `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"released_on":"2025-01-06"`
		// 已解除但缺少解除日期（解除信息错误）。
		releasedMissingDate = `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案"`
		// 解除日期早于冻结日期（解除信息错误）。
		releasedBeforeFrozen = `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-04"`
		// 缺少冻结日期的未解除冻结（原冻结信息缺项）。
		missingFrozenDate = `"reason":"诉讼","released":false`
		// 同时缺少冻结原因与冻结日期，但解除信息完整：解除信息不能补齐原冻结信息。
		releasedMissingBothOrigin = `"released":true,"release_reason":"结案","released_on":"2025-01-06"`
	)

	cases := map[string]struct {
		content  string
		wantAll  []string // 错误信息必须全部包含
		wantNone []string // 错误信息不得包含（被优先级压下的问题）
	}{
		"题目主例：编号靠前档案的解除问题让位于编号靠后档案的原冻结缺项": {
			// A-1 的 F-9 缺少解除原因，A-2 的 F-1 缺少冻结日期：
			// 必须指出 A-2、F-1 和缺少冻结日期，不能先报告 A-1 的解除问题。
			content: freezeErrorState(
				freezeErrorArchive("A-1", frz("F-9", releasedMissingReason)),
				freezeErrorArchive("A-2", frz("F-1", missingFrozenDate)),
			),
			wantAll:  []string{"A-2", "F-1", "冻结日期"},
			wantNone: []string{"A-1", "F-9", "解除"},
		},
		"调换两份档案在保存内容中的先后不改变报告": {
			// 与主例只有档案排列位置不同（A-2 写在前面），报告必须一致。
			content: freezeErrorState(
				freezeErrorArchive("A-2", frz("F-1", missingFrozenDate)),
				freezeErrorArchive("A-1", frz("F-9", releasedMissingReason)),
			),
			wantAll:  []string{"A-2", "F-1", "冻结日期"},
			wantNone: []string{"A-1", "F-9", "解除"},
		},
		"同一档案更早登记冻结的解除问题也要让位于后登记冻结的原冻结缺项": {
			// F-1 登记在前且已解除但缺少解除日期，F-2 登记在后且缺少冻结日期：
			// 必须报告 F-2 的原冻结缺项，不能按登记顺序先报 F-1 的解除问题。
			content: freezeErrorState(
				freezeErrorArchive("A-1",
					frz("F-1", releasedMissingDate),
					frz("F-2", missingFrozenDate),
				),
			),
			wantAll:  []string{"A-1", "F-2", "冻结日期"},
			wantNone: []string{"F-1", "解除"},
		},
		"同一档案更早登记冻结的日期倒置同样让位于后登记冻结的原冻结缺项": {
			content: freezeErrorState(
				freezeErrorArchive("A-1",
					frz("F-1", releasedBeforeFrozen),
					frz("F-2", `"frozen_on":"2025-02-01","released":false`),
				),
			),
			// F-2 缺少冻结原因。
			wantAll:  []string{"A-1", "F-2", "冻结原因"},
			wantNone: []string{"F-1", "解除", "2025-01-04"},
		},
		"完整的解除信息不能代替同一条冻结缺失的原冻结原因与日期": {
			// 已解除、解除原因与解除日期都完整，但原冻结原因与冻结日期都缺失：
			// 两项原冻结缺项都要说明，不能被解除信息顶替。
			content: freezeErrorState(
				freezeErrorArchive("A-1", frz("F-1", releasedMissingBothOrigin)),
			),
			wantAll:  []string{"A-1", "F-1", "冻结原因", "冻结日期"},
			wantNone: []string{},
		},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			dir := t.TempDir()
			writeStateFile(t, dir, tc.content)

			s, err := Open(dir)
			if err == nil {
				s.Close()
				t.Fatal("原冻结信息缺项与解除信息错误共同出现时不应打开成功")
			}
			if !errors.Is(err, ErrCorruptState) {
				t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
			}
			msg := err.Error()
			for _, want := range tc.wantAll {
				if !strings.Contains(msg, want) {
					t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
				}
			}
			for _, banned := range tc.wantNone {
				if strings.Contains(msg, banned) {
					t.Fatalf("错误信息不应包含被优先级压下的 %q，得到 %v", banned, err)
				}
			}
			// 打开失败不交付可用保管库，原保存内容保持原样。
			if got := readStateFile(t, dir); got != tc.content {
				t.Fatalf("打开失败后原文件被改动:\n%q", got)
			}
		})
	}
}

// 同类问题出现多处时，首个问题按档案编号文本升序、再按冻结历史登记顺序选出：
// 冻结编号大小、冻结日期先后与档案在保存内容中的排列位置都不能替代这一顺序。
func TestFreezeCorruptionFirstErrorOrdering(t *testing.T) {
	cases := map[string]struct {
		content  string
		wantAll  []string
		wantNone []string
	}{
		// —— 原冻结信息缺项之间的顺序 ——
		"原冻结缺项按登记顺序而非冻结编号大小": {
			// F-9 登记在前（缺原因），F-1 登记在后（缺日期）：
			// 按编号文本会先选 F-1，按登记顺序必须选 F-9。
			content: freezeErrorState(
				freezeErrorArchive("A-1",
					frz("F-9", `"frozen_on":"2025-01-05","released":false`),
					frz("F-1", `"reason":"诉讼","released":false`),
				),
			),
			wantAll:  []string{"A-1", "F-9", "冻结原因"},
			wantNone: []string{"F-1"},
		},
		"原冻结缺项按登记顺序而非冻结日期先后": {
			// 登记在前的冻结日期反而更晚（缺原因），日期更早的冻结登记在后
			// （缺日期）：不能按日期挑出后者。
			content: freezeErrorState(
				freezeErrorArchive("A-1",
					frz("F-1", `"reason":"诉讼","frozen_on":"2025-03-01","released":false`),
					frz("F-2", `"reason":"诉讼","released":false`),
				),
			),
			wantAll:  []string{"A-1", "F-2", "冻结日期"},
			wantNone: []string{"F-1"},
		},
		"原冻结缺项跨档案按编号文本升序（保存顺序 A-1 在前）": {
			content: freezeErrorState(
				freezeErrorArchive("A-1", frz("F-1", `"reason":"诉讼","released":false`)),
				freezeErrorArchive("A-2", frz("F-1", `"frozen_on":"2025-01-05","released":false`)),
			),
			wantAll:  []string{"A-1", "F-1", "冻结日期"},
			wantNone: []string{"A-2"},
		},
		"原冻结缺项跨档案按编号文本升序（保存顺序 A-2 在前）": {
			// 仅调换档案排列位置，报告必须与上一例一致。
			content: freezeErrorState(
				freezeErrorArchive("A-2", frz("F-1", `"frozen_on":"2025-01-05","released":false`)),
				freezeErrorArchive("A-1", frz("F-1", `"reason":"诉讼","released":false`)),
			),
			wantAll:  []string{"A-1", "F-1", "冻结日期"},
			wantNone: []string{"A-2"},
		},
		"同档案内缺日期登记在先要先于后登记的缺原因报告": {
			// 原冻结缺项是同一大类：登记顺序先于“原因先于日期”的条内规则，
			// 只有同一条记录两项同缺时才两项都说明。
			content: freezeErrorState(
				freezeErrorArchive("A-1",
					frz("F-1", `"reason":"诉讼","released":false`),
					frz("F-2", `"frozen_on":"2025-01-05","released":false`),
				),
			),
			wantAll:  []string{"A-1", "F-1", "冻结日期"},
			wantNone: []string{"F-2", "冻结原因"},
		},

		// —— 全部原冻结信息齐备后，解除信息错误才按同一顺序报告 ——
		"解除错误按登记顺序而非冻结编号大小": {
			content: freezeErrorState(
				freezeErrorArchive("A-1",
					frz("F-9", `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"released_on":"2025-01-06"`),
					frz("F-1", `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-04"`),
				),
			),
			// F-9 登记在前且缺解除原因；F-1 的日期倒置必须被压下。
			wantAll:  []string{"A-1", "F-9", "解除原因"},
			wantNone: []string{"F-1", "早于"},
		},
		"解除错误按登记顺序而非冻结日期先后": {
			content: freezeErrorState(
				freezeErrorArchive("A-1",
					frz("F-1", `"reason":"诉讼","frozen_on":"2025-03-01","released":true,"released_on":"2025-03-02"`),
					frz("F-2", `"reason":"诉讼","frozen_on":"2025-01-01","released":true,"release_reason":"结案","released_on":"2024-12-31"`),
				),
			),
			// F-1 登记在前（缺解除原因），F-2 虽日期更早且倒置也只能先报 F-1。
			wantAll:  []string{"A-1", "F-1", "解除原因"},
			wantNone: []string{"F-2", "早于"},
		},
		"解除错误跨档案按编号文本升序（保存顺序 A-1 在前）": {
			content: freezeErrorState(
				freezeErrorArchive("A-1", frz("F-1", `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案"`)),
				freezeErrorArchive("A-2", frz("F-1", `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-04"`)),
			),
			// A-1 缺解除日期；A-2 的日期倒置必须被压下。
			wantAll:  []string{"A-1", "F-1", "解除日期"},
			wantNone: []string{"A-2", "早于"},
		},
		"解除错误跨档案按编号文本升序（保存顺序 A-2 在前）": {
			content: freezeErrorState(
				freezeErrorArchive("A-2", frz("F-1", `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-04"`)),
				freezeErrorArchive("A-1", frz("F-1", `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案"`)),
			),
			wantAll:  []string{"A-1", "F-1", "解除日期"},
			wantNone: []string{"A-2", "早于"},
		},
		"同一条已解除记录同时缺解除原因与日期时先说明解除原因": {
			content: freezeErrorState(
				freezeErrorArchive("A-1",
					frz("F-1", `"reason":"诉讼","frozen_on":"2025-01-05","released":true`),
				),
			),
			wantAll: []string{"A-1", "F-1", "解除原因"},
		},
		"日期倒置错误同时给出解除日期与冻结日期": {
			content: freezeErrorState(
				freezeErrorArchive("A-1",
					frz("F-1", `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-04"`),
				),
			),
			wantAll: []string{"A-1", "F-1", "解除日期", "2025-01-04", "冻结日期", "2025-01-05"},
		},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			dir := t.TempDir()
			writeStateFile(t, dir, tc.content)

			s, err := Open(dir)
			if err == nil {
				s.Close()
				t.Fatal("存在同类冻结问题时不应打开成功")
			}
			if !errors.Is(err, ErrCorruptState) {
				t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
			}
			msg := err.Error()
			for _, want := range tc.wantAll {
				if !strings.Contains(msg, want) {
					t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
				}
			}
			for _, banned := range tc.wantNone {
				if strings.Contains(msg, banned) {
					t.Fatalf("错误信息不应包含顺序靠后的 %q，得到 %v", banned, err)
				}
			}
			if got := readStateFile(t, dir); got != tc.content {
				t.Fatalf("打开失败后原文件被改动:\n%q", got)
			}
		})
	}
}

// 保管库打开后保存内容才同时出现原冻结缺项与解除错误：重新打开必须失败且不
// 交付可用保管库，已有实例读取历史（含查询另一份正常档案）也必须按同样的
// 先后关系失败且不返回部分历史，原保存内容保持原样。
func TestFreezeCorruptionOrderingAfterOpenFailsReads(t *testing.T) {
	dir := t.TempDir()
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	reg(t, s, "A-1", "合同", "2020-01-01", "2026-12-31")
	reg(t, s, "A-2", "合同", "2020-01-01", "2026-12-31")
	reg(t, s, "A-3", "凭证", "2020-01-01", "2026-12-31")
	// A-1：F-1 已合法解除，F-2 未解除。
	if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
		t.Fatal(err)
	}
	if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-06")}); err != nil {
		t.Fatal(err)
	}
	if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计", FrozenOn: MustParseDate("2025-02-01")}); err != nil {
		t.Fatal(err)
	}
	// A-2：一条合法冻结。
	if err := s.Freeze(FreezeInput{ArchiveID: "A-2", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
		t.Fatal(err)
	}

	// 同时制造两类问题：A-1/F-1 去掉解除原因（解除信息错误），
	// A-2/F-1 去掉冻结日期（原冻结信息缺项）。
	rewriteState(t, dir, func(doc map[string]any) {
		a1 := doc["archives"].(map[string]any)["A-1"].(map[string]any)
		delete(a1["freezes"].([]any)[0].(map[string]any), "release_reason")
		a2 := doc["archives"].(map[string]any)["A-2"].(map[string]any)
		delete(a2["freezes"].([]any)[0].(map[string]any), "frozen_on")
	})
	corruptContent := readStateFile(t, dir)

	// 重新打开必须失败：按先后关系报告 A-2/F-1 的原冻结缺项，
	// 而不是 A-1/F-1 的解除问题，且不交付可用保管库。
	s2, err := Open(dir)
	if err == nil {
		s2.Close()
		t.Fatal("损坏共同出现时重新打开必须失败")
	}
	if s2 != nil {
		t.Fatal("打开失败不应交付可用保管库")
	}
	if !errors.Is(err, ErrCorruptState) {
		t.Fatalf("打开错误应为 ErrCorruptState，得到 %v", err)
	}
	msg := err.Error()
	for _, want := range []string{"A-2", "F-1", "冻结日期"} {
		if !strings.Contains(msg, want) {
			t.Fatalf("打开错误应包含 %q，得到 %v", want, err)
		}
	}
	if strings.Contains(msg, "解除") || strings.Contains(msg, "A-1") {
		t.Fatalf("不应先报告 A-1 的解除问题，得到 %v", err)
	}

	// 已有实例：直接读有问题的两份档案必须失败且不返回部分历史；
	// 查询另一份完全正常的档案 A-3 也同样失败。
	for _, id := range []string{"A-1", "A-2", "A-3"} {
		h, found, err := s.History(id)
		if !errors.Is(err, ErrCorruptState) {
			t.Fatalf("损坏后 History(%s) 必须返回 ErrCorruptState，得到 found=%v err=%v", id, found, err)
		}
		if found || h.ID != "" || len(h.Freezes) != 0 {
			t.Fatalf("损坏后 History(%s) 不得返回部分历史: found=%v history=%+v", id, found, h)
		}
	}

	// 读取失败不得触发重新保存，原保存内容保持原样。
	if got := readStateFile(t, dir); got != corruptContent {
		t.Fatalf("读取失败后原保存内容被改动:\n%q", got)
	}
}

// 合法情形对照组：未解除冻结没有解除信息仍是正常情况；解除日期等于冻结日期
// 且信息完整的记录仍可读取；全部冻结历史（未解除、当天解除、隔日解除）保持完整。
func TestFreezeCorruptionOrderingValidRecordsUnaffected(t *testing.T) {
	content := freezeErrorState(
		freezeErrorArchive("A-1",
			// 未解除：没有 release_reason / released_on 合法。
			frz("F-1", `"reason":"诉讼","frozen_on":"2025-01-05","released":false`),
			// 解除日期等于冻结日期：合法。
			frz("F-2", `"reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-05"`),
			// 隔日解除：合法。
			frz("F-3", `"reason":"审计","frozen_on":"2025-02-01","released":true,"release_reason":"完成","released_on":"2025-02-03"`),
		),
	)
	dir := t.TempDir()
	writeStateFile(t, dir, content)
	s, err := Open(dir)
	if err != nil {
		t.Fatalf("合法冻结历史应能打开: %v", err)
	}
	defer s.Close()

	h, found, err := s.History("A-1")
	if err != nil || !found {
		t.Fatalf("合法冻结历史应可查: found=%v err=%v", found, err)
	}
	if len(h.Freezes) != 3 {
		t.Fatalf("全部冻结历史应保持完整，得到 %d 条: %+v", len(h.Freezes), h.Freezes)
	}
	if h.Freezes[0].Released || h.Freezes[0].ReleaseReason != "" || !h.Freezes[0].ReleasedOn.IsZero() {
		t.Fatalf("F-1 应保持未解除且无解除信息: %+v", h.Freezes[0])
	}
	if !h.Freezes[1].Released ||
		!h.Freezes[1].ReleasedOn.Equal(h.Freezes[1].FrozenOn) ||
		h.Freezes[1].ReleaseReason != "结案" {
		t.Fatalf("F-2 应保留当天解除的完整信息: %+v", h.Freezes[1])
	}
	if !h.Freezes[2].Released ||
		h.Freezes[2].ReleasedOn.String() != "2025-02-03" ||
		h.Freezes[2].Reason != "审计" {
		t.Fatalf("F-3 应保留隔日解除的完整信息: %+v", h.Freezes[2])
	}
	if len(h.ActiveFreezes) != 1 || h.ActiveFreezes[0].ID != "F-1" {
		t.Fatalf("仅 F-1 仍算作未解除冻结，得到 %+v", h.ActiveFreezes)
	}
}

