24	// obstructionKinds 收集一份档案结果中的全部阻碍类别，保持出现顺序。
25	func obstructionKinds(r ArchiveCheckResult) []ObstructionKind {
26		kinds := make([]ObstructionKind, 0, len(r.Obstructions))
27		for _, o := range r.Obstructions {
28			kinds = append(kinds, o.Kind)
29		}
30		return kinds
31	}
