33	func TestCheckReadyWhenAllClear(t *testing.T) {
34		s := openTestStore(t)
35		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
36		reg(t, s, "A-2", "凭证", "2020-01-01", "2024-12-31")
37		// A-1 有一条已解除冻结，不应成为阻碍。
38		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-08")}); err != nil {
39			t.Fatal(err)
40		}
41		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-09")}); err != nil {
42			t.Fatal(err)
43		}
44	
45		// 截止日当天即到期；处理日期晚于截止日同样到期。
46		r := mustCheck(t, s, "APP-1", "2025-01-10", "A-2", "A-1")
47		if r.Status != CheckReady {
48			t.Fatalf("全部无阻碍应可以办理，得到 %s: %+v", r.Status, r.Results)
49		}
50		if r.Manifest != nil {
51			t.Fatalf("未成功使用的申请不应附清册: %+v", r.Manifest)
52		}
53		// 结果按提交顺序，而非编号排序。
54		if len(r.Results) != 2 || r.Results[0].ID != "A-2" || r.Results[1].ID != "A-1" {
55			t.Fatalf("结果应按提交顺序: %+v", r.Results)
56		}
57		first := r.Results[1]
58		if !first.Exists || first.Category != "合同" ||
59			!first.Start.Equal(MustParseDate("2020-01-01")) ||
60			!first.End.Equal(MustParseDate("2025-01-10")) || first.Destroyed {
61			t.Fatalf("已登记档案应显示类别、起算日、截止日和销毁状态: %+v", first)
62		}
63		if len(first.Obstructions) != 0 {
64			t.Fatalf("无阻碍档案不应列出阻碍: %+v", first.Obstructions)
65		}
