68	func TestCheckObstructionsAllKinds(t *testing.T) {
69		s := openTestStore(t)
70		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10") // 未到期
71		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-01-10") // 到期但有冻结
72		reg(t, s, "A-3", "图纸", "2020-01-01", "2025-01-08") // 在 2025-01-09 已到期、无冻结，可办
73		// A-2：一条未到期名单共用处理日期 2025-01-09，故 A-1、A-2 都未到期；
74		// 给 A-2 挂冻结验证“未到期 + 冻结”并列。
75		if err := s.Freeze(FreezeInput{ArchiveID: "A-2", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
76			t.Fatal(err)
77		}
78		if err := s.Freeze(FreezeInput{ArchiveID: "A-2", FreezeID: "F-2", Reason: "审计", FrozenOn: MustParseDate("2025-01-06")}); err != nil {
79			t.Fatal(err)
80		}
81		if err := s.Freeze(FreezeInput{ArchiveID: "A-2", FreezeID: "F-3", Reason: "巡检", FrozenOn: MustParseDate("2025-01-07")}); err != nil {
82			t.Fatal(err)
83		}
84		// F-2 已解除，不能作为阻碍，也不能打断其余冻结的历史顺序。
85		if err := s.Release(ReleaseInput{ArchiveID: "A-2", FreezeID: "F-2", Reason: "审计结束", ReleasedOn: MustParseDate("2025-01-08")}); err != nil {
86			t.Fatal(err)
87		}
88	
89		r := mustCheck(t, s, "APP-1", "2025-01-09", "A-1", "GHOST", "A-2", "A-3")
90		if r.Status != CheckBlocked {
91			t.Fatalf("存在阻碍应判存在阻碍，得到 %s", r.Status)
92		}
93		if len(r.Results) != 4 {
94			t.Fatalf("应逐份列出 4 条结果，得到 %d", len(r.Results))
95		}
96	
97		// 提交顺序保留。
98		gotIDs := []string{r.Results[0].ID, r.Results[1].ID, r.Results[2].ID, r.Results[3].ID}
99		if want := []string{"A-1", "GHOST", "A-2", "A-3"}; len(gotIDs) != len(want) {
100			t.Fatalf("顺序错误: %v", gotIDs)
101		} else {
102			for i := range want {
103				if gotIDs[i] != want[i] {
104					t.Fatalf("顺序错误: %v", gotIDs)
105				}
106			}
107		}
108	
109		// 不存在：单独标明，Exists 为 false，登记字段为零值，只有一条不存在阻碍。
110		ghost := r.Results[1]
111		if ghost.Exists || ghost.Category != "" || !ghost.Start.IsZero() || ghost.Destroyed {
112			t.Fatalf("不存在编号不应带登记字段: %+v", ghost)
113		}
114		if kinds := obstructionKinds(ghost); len(kinds) != 1 || kinds[0] != ObstructionMissing {
115			t.Fatalf("不存在编号应只有一条不存在阻碍: %+v", ghost.Obstructions)
116		}
117	
118		// 未到期：A-1 只报未到期。
119		if kinds := obstructionKinds(r.Results[0]); len(kinds) != 1 || kinds[0] != ObstructionNotExpired {
120			t.Fatalf("A-1 应只有未到期阻碍: %+v", r.Results[0].Obstructions)
121		}
122	
123		// A-2：未到期与两条未解除冻结并列，冻结顺序沿用冻结历史（F-1 后直接 F-3）。
124		a2 := r.Results[2]
125		kinds := obstructionKinds(a2)
126		if len(kinds) != 3 || kinds[0] != ObstructionNotExpired ||
