158			t.Fatalf("含已销毁档案应判存在阻碍，得到 %s", r.Status)
159		}
160		res := r.Results[0]
161		if !res.Exists || !res.Destroyed {
162			t.Fatalf("已销毁档案应存在且销毁状态为真: %+v", res)
163		}
164		if len(res.Obstructions) != 1 || res.Obstructions[0].Kind != ObstructionDestroyed {
165			t.Fatalf("已销毁档案应只列已销毁阻碍: %+v", res.Obstructions)
166		}
167		obs := res.Obstructions[0]
168		if obs.ManifestApplicationID != "APP-9" || !obs.ProcessedOn.Equal(m.ProcessedOn) {
169			t.Fatalf("已销毁阻碍应附所属清册申请编号和处理日期: %+v", obs)
