340		m, found, err := s.GetManifest("APP-1")
341		if err != nil || !found {
342			t.Fatalf("原清册应仍可查: found=%v err=%v", found, err)
343		}
344		if m.ApplicationID != "APP-1" || len(m.Entries) != 2 || m.Entries[0].Category != "合同" {
345			t.Fatalf("修改报告不得影响保存的清册: %+v", m)
