353	// TestCheckSnapshotConsistencyUnderConcurrency 验证多个本机程序并发办理时，
354	// 同一份报告里的档案与清册必定来自同一个已保存状态：A-1、A-2 在一次销毁中
355	// 原子地进入同一份清册，因此任何一次核对看到的两者销毁状态必须一致，
356	// 且已销毁时所属清册信息必定同时可见。
357	func TestCheckSnapshotConsistencyUnderConcurrency(t *testing.T) {
358		dir := t.TempDir()
359		setup, err := Open(dir)
360		if err != nil {
361			t.Fatal(err)
362		}
363		reg(t, setup, "A-1", "合同", "2020-01-01", "2025-01-10")
364		reg(t, setup, "A-2", "凭证", "2020-01-01", "2025-01-10")
365		if err := setup.Close(); err != nil {
366			t.Fatal(err)
367		}
368	
369		const readers = 8
370		const iterations = 500
371		var wg sync.WaitGroup
372		start := make(chan struct{})
373		var failures int64
374	
375		// 读者们持续核对：一个用未使用编号看逐份状态，一个直接核对已成功编号。
376		for i := 0; i < readers; i++ {
377			wg.Add(1)
378			go func() {
379				defer wg.Done()
380				sr, err := Open(dir)
381				if err != nil {
382					atomic.AddInt64(&failures, 1)
383					return
384				}
385				defer sr.Close()
386				<-start
387				for k := 0; k < iterations; k++ {
388					r, err := sr.Check(CheckRequest{
389						ApplicationID: "APP-R", ProcessedOn: MustParseDate("2025-01-10"),
390						ArchiveIDs: []string{"A-1", "A-2"},
391					})
392					if err != nil {
393						atomic.AddInt64(&failures, 1)
394						return
395					}
396					if r.Status != CheckReady && r.Status != CheckBlocked {
397						t.Errorf("未使用编号核对只应可以办理或存在阻碍，得到 %s", r.Status)
398						return
399					}
400					if len(r.Results) != 2 {
401						t.Errorf("报告应含两份档案，得到 %d", len(r.Results))
402						return
403					}
404					d1, d2 := r.Results[0].Destroyed, r.Results[1].Destroyed
405					if d1 != d2 {
406						t.Errorf("报告混入了销毁前后的不同状态: %+v", r.Results)
407						return
408					}
409					if d1 {
410						for _, res := range r.Results {
411							obs := res.Obstructions
412							if len(obs) != 1 || obs[0].Kind != ObstructionDestroyed ||
413								obs[0].ManifestApplicationID != "APP-1" ||
414								!obs[0].ProcessedOn.Equal(MustParseDate("2025-01-10")) {
415								t.Errorf("已销毁档案的所属清册必须与状态同快照可见: %+v", obs)
416								return
417							}
418						}
419					}
420	
421					// 直接核对该已成功编号：要么尚未生成（可以办理且无清册），
422					// 要么可以取回原清册，二者必居其一，不能出现半生成状态。
423					rr, err := sr.Check(CheckRequest{
424						ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"),
425						ArchiveIDs: []string{"A-2", "A-1"},
426					})
427					if err != nil {
428						t.Errorf("核对已成功编号不应失败: %v", err)
429						return
430					}
431					switch rr.Status {
432					case CheckReady:
433						if rr.Manifest != nil {
434							t.Errorf("可以办理时不应带清册: %+v", rr.Manifest)
435							return
436						}
437					case CheckReplayable:
438						if rr.Manifest == nil || len(rr.Manifest.Entries) != 2 {
439							t.Errorf("可取回时原清册必须完整: %+v", rr.Manifest)
440							return
441						}
442					default:
443						t.Errorf("已成功编号不应出现其他状态: %s", rr.Status)
444						return
445					}
446				}
447			}()
448		}
449	
450		// 办理者在读者开始后销毁两份档案（单次原子办理）。
451		wg.Add(1)
452		go func() {
453			defer wg.Done()
454			sm, err := Open(dir)
455			if err != nil {
456				atomic.AddInt64(&failures, 1)
457				close(start)
458				return
459			}
460			defer sm.Close()
461			close(start)
462			if _, err := sm.Destroy(DestructionRequest{
463				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"),
464				ArchiveIDs: []string{"A-1", "A-2"},
465			}); err != nil {
466				t.Errorf("并发销毁失败: %v", err)
467			}
468		}()
469		wg.Wait()
470	
471		if atomic.LoadInt64(&failures) != 0 {
472			t.Fatalf("并发核对中出现打开失败等错误")
473		}
474	}
